/* ==========================================================================
 * flipbook.js —— 序列帧特效（Blender/Mantaflow 预渲染的 sprite sheet）
 *
 * Sheets + manifest: assets/vfx/vfx.json, generated by tools/blender/vfx/build_all.py.
 * Texels are PREMULTIPLIED alpha, sRGB values sampled raw and written raw (like every other
 * unlit sprite here: no colour-space conversion), blended with ONE / ONE_MINUS_SRC_ALPHA.
 * Additive sheets write alpha 0, so the same blend equation becomes pure additive.
 *
 *   import { loadFlipbooks, spawnFlipbook, updateFlipbooks } from './flipbook.js';
 *   await loadFlipbooks();                       // manifest + all sheets (optional preload)
 *   const h = spawnFlipbook(scene, 'hit_heavy', { x, y, z, scale: 1.2, tint: '#ffd0a0' });
 *   updateFlipbooks(dt);                         // once per frame, dt in seconds
 *
 * spawnFlipbook options (all optional):
 *   x, y, z          world position of the pivot (manifest pivot: [u, v] of the frame, v = 0 bottom)
 *   scale            multiplies the manifest `size` (frame width in world units); sx / sy override
 *   flipX            mirror horizontally (facing left)
 *   rotation         radians, in the sprite plane (billboard) / around +Y (ground decal)
 *   tint             '#rrggbb' | 0xrrggbb | THREE.Color | [r,g,b] (multiplies the sheet colour)
 *   alpha            opacity 0..1 (default 1)
 *   billboard        true: faces the camera; false: lies flat on the ground (XZ, image up = -Z)
 *                    (default from the manifest: decals are false)
 *   variant          which variant of a multi-variant sheet (default random)
 *   fps, speed       playback rate override / multiplier
 *   loop             override manifest loop; looping effects run until `duration` or stop()
 *   duration         seconds of life for loops / single-frame decals (`hold`), default 1 s
 *   fadeIn, fadeOut  seconds (default 0 / 0.12 for one-shots, 0.15 / 0.25 for loops & holds)
 *   delay            seconds before it appears
 *   followObject     THREE.Object3D to stick to (its world position + x/y/z as offset)
 *   blendFrames      cross-fade adjacent frames (default true) — smoother at low fps
 *   onEnd            callback(handle) when it finishes
 * Returns a handle: { name, alive, t, stop(fadeSeconds?), setPosition(x,y,z) } (pooled — do not
 * keep it after it ended: check handle.alive / handle.id).
 *
 * One InstancedBufferGeometry mesh + one ShaderMaterial per sheet per scene; per-instance data in
 * a few typed arrays updated in place — no allocations per frame.
 * ========================================================================== */
import * as THREE from 'three';

const DEFAULT_BASE = 'assets/vfx/';
const CAP = 64;                       // max live instances per sheet (oldest one is recycled)

let manifest = null;
let base = DEFAULT_BASE;
let loadingManifest = null;
const sheets = new Map();             // name -> Sheet
const texLoader = new THREE.TextureLoader();
const _v = new THREE.Vector3();
const _c = new THREE.Color();
let nextId = 1;

const VERT = /* glsl */`
attribute vec3 aPos;      // pivot, world
attribute vec4 aSize;     // w, h, rotation, mode (0 billboard, 1 ground)
attribute vec4 aFrame;    // frameA, frameB, blend, -
attribute vec4 aColor;    // tint rgb, alpha
uniform vec2 uPivot;
uniform vec2 uGrid;       // cols, rows
varying vec2 vUvA;
varying vec2 vUvB;
varying float vBlend;
varying vec4 vColor;
vec2 cell(float k, vec2 uv) {
  float col = mod(k, uGrid.x);
  float row = floor(k / uGrid.x);
  return vec2((col + uv.x) / uGrid.x, 1.0 - (row + 1.0 - uv.y) / uGrid.y);
}
void main() {
  vec2 uv = position.xy + 0.5;
  vec2 p = (uv - uPivot) * aSize.xy;     // w < 0 (flipX) mirrors the quad, and with it the texture
  float c = cos(aSize.z), s = sin(aSize.z);
  p = vec2(c * p.x - s * p.y, s * p.x + c * p.y);
  if (aSize.w < 0.5) {
    vec4 mv = viewMatrix * vec4(aPos, 1.0);
    mv.xy += p;
    gl_Position = projectionMatrix * mv;
  } else {
    gl_Position = projectionMatrix * viewMatrix * vec4(aPos + vec3(p.x, 0.0, -p.y), 1.0);
  }
  vUvA = cell(aFrame.x, uv);
  vUvB = cell(aFrame.y, uv);
  vBlend = aFrame.z;
  vColor = aColor;
}`;

const FRAG = /* glsl */`
uniform sampler2D uMap;
uniform float uAdd;
varying vec2 vUvA;
varying vec2 vUvB;
varying float vBlend;
varying vec4 vColor;
void main() {
  vec4 t = mix(texture2D(uMap, vUvA), texture2D(uMap, vUvB), vBlend);
  t *= vColor.a;
  if (t.a < 0.002 && max(t.r, max(t.g, t.b)) < 0.002) discard;
  gl_FragColor = vec4(t.rgb * vColor.rgb, t.a * (1.0 - uAdd));
}`;

function geometry(cap) {
  const g = new THREE.InstancedBufferGeometry();
  const plane = new THREE.PlaneGeometry(1, 1);
  g.index = plane.index;
  g.setAttribute('position', plane.getAttribute('position'));
  const mk = (n) => {
    const a = new THREE.InstancedBufferAttribute(new Float32Array(cap * n), n);
    a.setUsage(THREE.DynamicDrawUsage);
    return a;
  };
  g.setAttribute('aPos', mk(3));
  g.setAttribute('aSize', mk(4));
  g.setAttribute('aFrame', mk(4));
  g.setAttribute('aColor', mk(4));
  g.instanceCount = 0;
  return g;
}

class Sheet {
  constructor(name, def) {
    this.name = name;
    this.def = def;
    this.tex = null;
    this.ready = false;
    this.meshes = new Map();          // scene -> mesh
    this.live = [];                   // active handles (dense)
    this.pool = [];
    this.mat = new THREE.ShaderMaterial({
      uniforms: {
        uMap: { value: null },
        uGrid: { value: new THREE.Vector2(def.cols, def.rows) },
        uPivot: { value: new THREE.Vector2(def.pivot[0], def.pivot[1]) },
        uAdd: { value: def.blending === 'additive' ? 1 : 0 },
      },
      vertexShader: VERT,
      fragmentShader: FRAG,
      transparent: true,
      depthWrite: false,
      depthTest: true,
      side: THREE.DoubleSide,
      blending: THREE.CustomBlending,
      blendEquation: THREE.AddEquation,
      blendSrc: THREE.OneFactor,
      blendDst: THREE.OneMinusSrcAlphaFactor,
      blendSrcAlpha: THREE.OneFactor,
      blendDstAlpha: THREE.OneMinusSrcAlphaFactor,
      fog: false,
    });
  }
  load() {
    if (this.loading) return this.loading;
    this.loading = new Promise((res) => {
      texLoader.load(base + this.def.file, (t) => {
        t.colorSpace = THREE.NoColorSpace;   // raw sRGB in, raw out (premultiplied)
        t.premultiplyAlpha = false;
        t.generateMipmaps = true;
        t.minFilter = THREE.LinearMipmapLinearFilter;
        t.magFilter = THREE.LinearFilter;
        t.wrapS = t.wrapT = THREE.ClampToEdgeWrapping;
        t.needsUpdate = true;
        this.tex = t;
        this.mat.uniforms.uMap.value = t;
        this.ready = true;
        for (const m of this.meshes.values()) m.visible = true;
        res(this);
      }, undefined, () => { console.warn('[flipbook] failed to load', this.def.file); res(this); });
    });
    return this.loading;
  }
  mesh(scene) {
    let m = this.meshes.get(scene);
    if (!m) {
      m = new THREE.Mesh(geometry(CAP), this.mat);
      m.name = 'flipbook:' + this.name;
      m.frustumCulled = false;
      m.renderOrder = this.def.blending === 'additive' ? 12 : 11;
      m.visible = this.ready;
      scene.add(m);
      this.meshes.set(scene, m);
    }
    return m;
  }
}

function sheetOf(name) {
  if (!manifest) return null;
  let s = sheets.get(name);
  if (!s) {
    const def = manifest[name];
    if (!def || name.startsWith('_')) return null;
    s = new Sheet(name, def);
    sheets.set(name, s);
  }
  return s;
}

/** load the manifest (and, unless names === false, the sheets: all or the listed names) */
export function loadFlipbooks(names, baseUrl) {
  if (baseUrl) base = baseUrl.endsWith('/') ? baseUrl : baseUrl + '/';
  if (!loadingManifest) {
    loadingManifest = fetch(base + 'vfx.json').then((r) => r.json()).then((j) => { manifest = j; return j; })
      .catch((e) => { console.warn('[flipbook] no manifest', e); manifest = {}; return manifest; });
  }
  return loadingManifest.then(() => {
    if (names === false) return manifest;
    const list = names || Object.keys(manifest).filter((k) => !k.startsWith('_'));
    return Promise.all(list.map((n) => { const s = sheetOf(n); return s ? s.load() : null; })).then(() => manifest);
  });
}

export function flipbookNames() { return manifest ? Object.keys(manifest).filter((k) => !k.startsWith('_')) : []; }
export function getFlipbookDef(name) { return manifest ? manifest[name] || null : null; }

function toColor(tint, out) {
  if (tint == null) return out.setRGB(1, 1, 1);
  if (tint.isColor) return out.copy(tint);
  if (Array.isArray(tint)) return out.setRGB(tint[0], tint[1], tint[2]);
  return out.set(tint);
}

function stopHandle(fade) {
  if (!this.alive) return;
  const f = fade == null ? 0.15 : fade;
  const remaining = this.life - this.t;
  if (f <= 0) { this.life = this.t; return; }
  if (remaining > f || this.life === Infinity) { this.life = this.t + f; this.fadeOut = f; }
}
function setPos(x, y, z) { this.x = x; this.y = y; this.z = z; }

/** spawn an effect; returns a pooled handle (or null if the name is unknown / manifest not loaded yet) */
export function spawnFlipbook(scene, name, o = {}) {
  if (!manifest) { loadFlipbooks(false); return null; }
  const s = sheetOf(name);
  if (!s) return null;
  if (!s.ready) s.load();
  const d = s.def;
  s.mesh(scene);
  let h;
  if (s.live.length >= CAP) {          // recycle the oldest
    h = s.live[0];
    finish(s, 0, false);
  }
  h = s.pool.pop() || { stop: stopHandle, setPosition: setPos, color: new THREE.Color() };
  h.id = nextId++;
  h.name = name;
  h.sheet = s;
  h.scene = scene;
  h.alive = true;
  h.x = o.x || 0; h.y = o.y || 0; h.z = o.z || 0;
  const sc = o.scale == null ? 1 : o.scale;
  h.w = d.size * (o.sx == null ? sc : o.sx);
  h.h = (d.size / d.aspect) * (o.sy == null ? sc : o.sy);
  if (o.flipX) h.w = -h.w;
  h.rot = o.rotation || 0;
  h.mode = (o.billboard == null ? d.billboard !== false : !!o.billboard) ? 0 : 1;
  toColor(o.tint, h.color);
  h.alpha = o.alpha == null ? 1 : o.alpha;
  h.variant = o.variant == null ? Math.floor(Math.random() * (d.variants || 1)) : Math.min(o.variant, (d.variants || 1) - 1);
  h.fps = (o.fps || d.fps) * (o.speed || 1);
  h.loop = o.loop == null ? !!d.loop : !!o.loop;
  h.hold = d.frames <= 1 || !!d.hold;
  const oneShot = !h.loop && !h.hold;
  h.life = oneShot ? d.frames / h.fps : (o.duration == null ? 1 : o.duration);
  h.fadeIn = o.fadeIn == null ? (oneShot ? 0 : 0.15) : o.fadeIn;
  h.fadeOut = o.fadeOut == null ? (oneShot ? 0.12 : 0.25) : o.fadeOut;
  h.t = -(o.delay || 0);
  h.follow = o.followObject || null;
  h.blendFrames = o.blendFrames !== false;
  h.onEnd = o.onEnd || null;
  h.slot = s.live.length;
  s.live.push(h);
  return h;
}

function finish(s, i, callEnd) {
  const h = s.live[i];
  const last = s.live.pop();
  if (last !== h) { s.live[i] = last; last.slot = i; }
  h.alive = false;
  h.follow = null;
  if (callEnd && h.onEnd) { const cb = h.onEnd; h.onEnd = null; cb(h); }
  h.onEnd = null;
  h.scene = null;
  s.pool.push(h);
}

/** advance all effects; call once per rendered frame */
export function updateFlipbooks(dt) {
  for (const s of sheets.values()) {
    if (!s.live.length && !s.dirty) continue;
    const d = s.def, frames = d.frames;
    // advance + retire
    for (let i = s.live.length - 1; i >= 0; i--) {
      const h = s.live[i];
      h.t += dt;
      if (h.t >= h.life) finish(s, i, true);
    }
    // write instance data, per scene mesh
    for (const [scene, mesh] of s.meshes) {
      const g = mesh.geometry;
      const P = g.attributes.aPos.array, S = g.attributes.aSize.array, F = g.attributes.aFrame.array, C = g.attributes.aColor.array;
      let n = 0;
      for (let i = 0; i < s.live.length; i++) {
        const h = s.live[i];
        if (h.scene !== scene || h.t < 0) continue;
        let x = h.x, y = h.y, z = h.z;
        if (h.follow) { h.follow.getWorldPosition(_v); x += _v.x; y += _v.y; z += _v.z; }
        let f = h.t * h.fps, fa, fb, bl;
        if (h.hold) { fa = fb = Math.min(frames - 1, Math.floor(f)); bl = 0; }
        else if (h.loop) { f %= frames; fa = Math.floor(f); fb = (fa + 1) % frames; bl = f - fa; }
        else { f = Math.min(f, frames - 1); fa = Math.floor(f); fb = Math.min(fa + 1, frames - 1); bl = f - fa; }
        if (!h.blendFrames) bl = 0;
        const off = h.variant * frames;
        let a = h.alpha;
        if (h.fadeIn > 0 && h.t < h.fadeIn) a *= h.t / h.fadeIn;
        const rem = h.life - h.t;
        if (h.fadeOut > 0 && rem < h.fadeOut) a *= Math.max(0, rem / h.fadeOut);
        const j3 = n * 3, j4 = n * 4;
        P[j3] = x; P[j3 + 1] = y; P[j3 + 2] = z;
        S[j4] = h.w; S[j4 + 1] = h.h; S[j4 + 2] = h.rot; S[j4 + 3] = h.mode;
        F[j4] = fa + off; F[j4 + 1] = fb + off; F[j4 + 2] = bl;
        C[j4] = h.color.r; C[j4 + 1] = h.color.g; C[j4 + 2] = h.color.b; C[j4 + 3] = a;
        n++;
      }
      g.instanceCount = n;
      for (const k of ['aPos', 'aSize', 'aFrame', 'aColor']) {
        const at = g.attributes[k];
        at.clearUpdateRanges();
        if (n) { at.addUpdateRange(0, n * at.itemSize); at.needsUpdate = true; }
      }
    }
    s.dirty = s.live.length > 0;
  }
}

/** stop / remove everything (e.g. on stage change); keeps textures */
export function clearFlipbooks() {
  for (const s of sheets.values()) {
    while (s.live.length) finish(s, s.live.length - 1, false);
    s.dirty = true;
  }
}

/** remove the per-scene meshes of a scene that is being thrown away */
export function detachFlipbooks(scene) {
  for (const s of sheets.values()) {
    const m = s.meshes.get(scene);
    if (m) { scene.remove(m); m.geometry.dispose(); s.meshes.delete(scene); }
    for (let i = s.live.length - 1; i >= 0; i--) if (s.live[i].scene === scene) finish(s, i, false);
  }
}

export const Flipbook = { load: loadFlipbooks, spawn: spawnFlipbook, update: updateFlipbooks, clear: clearFlipbooks,
  detach: detachFlipbooks, names: flipbookNames, def: getFlipbookDef };
